From 6b1f231dc685c661f0dbc4fc20a6a2bea195b32b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:04:15 +0100
Subject: [PATCH] applets/taskmanager: show an OSD when muting from the audio
 indicator

Clicking the speaker badge on a task muted the app with only a small
change to the badge as feedback, so accidental clicks went unnoticed.
It now shows the "App Muted" OSD used for players, and volume on unmute.

BUG: 432203
---
 applets/taskmanager/qml/AudioStream.qml | 11 +++++++++--
 applets/taskmanager/qml/main.qml        | 12 ++++++++++++
 2 files changed, 21 insertions(+), 2 deletions(-)

diff --git a/applets/taskmanager/qml/AudioStream.qml b/applets/taskmanager/qml/AudioStream.qml
index bfcc47fd63..14ce6bbd0e 100644
--- a/applets/taskmanager/qml/AudioStream.qml
+++ b/applets/taskmanager/qml/AudioStream.qml
@@ -91,7 +91,14 @@ Item {
     opacity: 0
     visible: opacity > 0

-    Keys.onReturnPressed: event => toggleMuted()
+    function toggleMutedWithOsd(): void {
+        const wasMuted = task.muted;
+        task.toggleMuted();
+        const volume = Math.max(...task.audioStreams.map(stream => stream.volume));
+        task.tasksRoot.showAudioStreamOsd(task.appName || model.display, wasMuted ? Math.round(volume / pulseAudio.item.normalVolume * 100) : 0);
+    }
+
+    Keys.onReturnPressed: event => toggleMutedWithOsd()
     Keys.onEnterPressed: event => Keys.returnPressed(event);
     Keys.onSpacePressed: event => Keys.returnPressed(event);

@@ -110,7 +117,7 @@ Item {
         id: tapHandler
         gesturePolicy: TapHandler.ReleaseWithinBounds // Exclusive grab
         enabled: Plasmoid.configuration.interactiveMute
-        onTapped: (eventPoint, button) => toggleMuted()
+        onTapped: (eventPoint, button) => toggleMutedWithOsd()
     }

     PlasmaExtras.Highlight {
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..04045f0c45 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -124,6 +124,18 @@ PlasmoidItem {
         return DBus.SessionBus.asyncCall({service: "org.kde.KWin.Effect.WindowView1", path: "/org/kde/KWin/Effect/WindowView1", iface: "org.kde.KWin.Effect.WindowView1", member: "activate", arguments: [winIds.map(s => String(s))], signature: "(as)"});
     }

+    function showAudioStreamOsd(appName: string, percent: int): DBus.DBusPendingReply {
+        let icon = "audio-volume-muted";
+        if (percent > 75) {
+            icon = "audio-volume-high";
+        } else if (percent > 25) {
+            icon = "audio-volume-medium";
+        } else if (percent > 0) {
+            icon = "audio-volume-low";
+        }
+        return DBus.SessionBus.asyncCall({service: "org.kde.plasmashell", path: "/org/kde/osdService", iface: "org.kde.osdService", member: "mediaPlayerVolumeChanged", arguments: [percent, appName, icon], signature: "(iss)"});
+    }
+
     function publishIconGeometries(taskItems: /*list<Item>*/var): void {
         if (TaskManagerApplet.TaskTools.taskManagerInstanceCount >= 2) {
             return;
-- 
